  FT["MY-H5264"] = {"id":"MY-H5264","coverage":"full","language":"ms","sourceName":"Attorney General's Chambers (AGC) Malaysia — Laws of Malaysia","sourceUrl":"https://lom.agc.gov.my/act-view.php?type=pua&no=P.U. (A) 378/2021&status=PRINCIPAL","fetchedAt":"2026-10-28","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"2021年图书馆资料交存（附表1修正）令","en":"DEPOSIT OF LIBRARY MATERIAL (AMENDMENT OF SCHEDULE 1) ORDER 2021","orig":"DEPOSIT OF LIBRARY MATERIAL (AMENDMENT OF SCHEDULE 1) ORDER 2021","ms":"Perintah Penyerahan Bahan Perpustakaan (Pindaan Jadual 1) 2021","vi":"Lệnh về Nộp lưu chiểu tài liệu thư viện (Sửa đổi Phụ lục 1) năm 2021","th":"คำสั่งการส่งมอบวัสดุห้องสมุด (การแก้ไขตารางที่ 1) ค.ศ. 2021","id":"Perintah Penyerahan Bahan Perpustakaan (Perubahan Lampiran 1) Tahun 2021"},"level":"regulation","category":"04_劳工与行政法","status":"active","docNumber":"PUA378","issuingBody":"马来西亚国会（Dewan Rakyat）","promulgatedDate":"2021","completenessNote":"全文：第 1 条至第 2 条；逐字未改写（源自厂商 OCR 文本）。","textQuality":"ocr-vendor","sourceFile":"MY\\en\\TXT文本\\04_劳工与行政法\\2021_P.U.(A)378-2021_DEPOSIT OF LIBRARY MATERIAL (AMENDMENT OF SCHEDULE 1) ORDER 2021.txt","country":"MY","countryName":"马来西亚","layer":"intl","articles":[{"id":"MY-H5264-A1","no":1,"noLabel":{"en":"Section 1"},"text":{"ms":"1. (1) Perintah ini bolehlah dinamakan Perintah Penyerahan\n\nBahan Perpustakaan (Pindaan Jadual 1) 2021.\n\n(2) Perintah ini mula berkuat kuasa pada 8 Oktober 2021.\n\nPindaan Jadual 1"}},{"id":"MY-H5264-A2","no":2,"noLabel":{"en":"Section 2"},"text":{"ms":"2. Akta Penyerahan Bahan Perpustakaan 1986 dipinda dengan menggantikan\n\nJadual 1 dengan jadual yang berikut:\n\n\"JADUAL 1\n\n[Subseksyen 4(1) dan (2)]\n\nBILANGAN NASKHAH BAHAN PERPUSTAKAAN\n\nYANG PERLU DISERAH\n\nBahan perpustakaan Bilangan naskhah"}}],"pack":"my-11"};
